import sys

def mod_exp(base, exp, mod):
    res = 1
    while exp:
        if exp & 1:
            res = (res * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return res

def array_add(a, b, N, mod):
    for i in range(N + 1):
        a[i] = (a[i] + b[i]) % mod

def array_subtract(a, b, N, mod):
    for i in range(N + 1):
        a[i] = (a[i] - b[i]) % mod

def array_multiply(res, a, b, N, mod):
    buffer = [0] * (N + 1)
    for i in range(N + 1):
        for j in range(i + 1):
            buffer[i] = (buffer[i] + a[j] * b[i - j]) % mod
    for i in range(N + 1):
        res[i] = buffer[i]

def forward_transform(a, N, n, Lg, a_size):
    for i in range(N):
        for msk in range(n, -1, -1):
            if (msk >> i) & 1:
                array_add(a[msk], a[msk ^ (1 << i)], N, mod)

def inverse_transform(a, N, n, Lg, a_size):
    for i in range(N):
        for msk in range(n, -1, -1):
            if (msk >> i) & 1:
                array_subtract(a[msk], a[msk ^ (1 << i)], N, mod)

def main():
    input_data = sys.stdin.read().strip().split()
    n_input = int(input_data[0])
    K = int(input_data[1])
    mod = int(input_data[2])

    total = mod_exp(K, n_input, mod)
    if n_input & 1:
        print(total)
        return

    N = bin(n_input).count('1')
    original_n = n_input
    pos = []
    for i in range(18):
        if (n_input >> i) & 1:
            pos.append(i)

    n = (1 << N) - 1

    Max = (1 << 18) + 10
    factorial = [1] * Max
    inv_factorial = [1] * Max

    for i in range(1, Max):
        factorial[i] = (factorial[i - 1] * i) % mod

    inv_factorial[Max - 1] = mod_exp(factorial[Max - 1], mod - 2, mod)
    for i in range(Max - 2, -1, -1):
        inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % mod

    matrix = [[0] * (N + 3) for _ in range(n + 1)]
    buffer2 = [0] * (N + 3)
    buffer = [0] * (N + 3)

    for i in range(n + 1):
        val = 0
        for j in range(N):
            if (i >> j) & 1:
                val += 1 << pos[j]
        matrix[i][bin(i).count('1')] = inv_factorial[val]

    # Forward transform
    for i in range(N):
        for msk in range(n, -1, -1):
            if (msk >> i) & 1:
                array_add(matrix[msk], matrix[msk ^ (1 << i)], N, mod)

    for i in range(n + 1):
        K_copy = K
        buffer2 = [0] * (N + 3)
        buffer2[0] = 1
        while K_copy:
            if K_copy & 1:
                array_multiply(buffer2, buffer2, matrix[i], N, mod)
            array_multiply(matrix[i], matrix[i], matrix[i], N, mod)
            K_copy >>= 1
        matrix[i] = buffer2[:]

    # Inverse transform
    for i in range(N):
        for msk in range(n, -1, -1):
            if (msk >> i) & 1:
                array_subtract(matrix[msk], matrix[msk ^ (1 << i)], N, mod)

    answer = (total - (matrix[n][N] * factorial[original_n]) % mod) % mod
    print(answer)

if __name__ == "__main__":
    main()

